package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.Timestamp;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.learning.courseprogressshare.v1.*;
/** Explicit, participant-owned completion summary snapshots; never exposes private Study steps. */
final class CourseProgressShareStore {
 record Share(UUID shareId,UUID groupId,UUID spaceId,UUID courseId,UUID participantId,long version,String state,long policyVersion,long membershipVersion,UUID enrollmentId,long enrollmentVersion,long courseVersion,long progressVersion,int completedStudies,int totalStudies,String audience,String updatedAt) {}
 record Preview(long progressVersion,int completedStudies,int totalStudies) {}
 record View(CourseContextClient.Sharing context,Share share,Preview preview,boolean effectiveShared) {}
 record Summary(UUID shareId,UUID participantId,int completedStudies,int totalStudies,String sharedAt) {}
 record Page(List<Summary> items,UUID nextAfter) {}
 record Scan(List<Share> items,UUID nextAfter) {}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Share snapshot) {}
 record History(List<Revision> items,Long nextBefore) {}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final CourseProgressStore progress;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 CourseProgressShareStore(DataSource source,CourseProgressStore progress,Clock clock){sql=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.progress=progress;this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException error(HttpStatus status,String message){return new ResponseStatusException(status,message);}
 private Share own(CourseContextClient.Reference ref){var rows=sql.query("SELECT snapshot::text FROM course_progress_share WHERE group_id=? AND space_id=? AND course_id=? AND participant_id=?",(rs,n)->json.readValue(rs.getString(1),Share.class),ref.groupId(),ref.spaceId(),ref.courseId(),ref.principalId());return rows.isEmpty()?null:rows.getFirst();}
 static boolean effective(Share s,CourseContextClient.Sharing a){var r=a.learning();return s!=null&&a.enabled()&&s.state().equals("SHARED")&&s.groupId().equals(r.groupId())&&s.spaceId().equals(r.spaceId())&&s.courseId().equals(r.courseId())&&s.participantId().equals(r.principalId())&&s.policyVersion()==a.policyVersion()&&s.membershipVersion()==a.membershipVersion()&&"ENROLLED".equals(r.enrollmentState())&&s.enrollmentId().equals(r.enrollmentId())&&s.enrollmentVersion()==r.enrollmentVersion();}
 private Preview preview(CourseProgressStore.Progress p){return new Preview(p.version(),(int)p.steps().stream().filter(v->v.status().equals("COMPLETED")).count(),p.steps().size());}
 View get(CourseContextClient.Sharing a){var share=own(a.learning());return new View(a,share,preview(progress.get(a.learning())),effective(share,a));}
 Share change(CourseContextClient.Sharing a,long expected,String state,long sourceVersion,String trace){CourseContextClient.validate(a.learning());if(expected<0||state==null||!Set.of("SHARED","WITHDRAWN").contains(state)||trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw RoadmapGraph.bad();var ref=a.learning();if(state.equals("SHARED")&&(!ref.writable()||!a.enabled()||a.policyVersion()<1||a.membershipVersion()<1||sourceVersion<1))throw error(HttpStatus.CONFLICT,"Current participation, policy and saved progress required");
  return tx.execute(s->{sql.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",rs->{},ref.spaceId()+":"+ref.courseId()+":"+ref.principalId());var old=own(ref);if(expected!=(old==null?0:old.version()))throw error(HttpStatus.PRECONDITION_FAILED,"Shared summary changed; refresh");if(state.equals("WITHDRAWN")&&(old==null||old.state().equals(state)))return old;
   var p=progress.get(ref);if(state.equals("SHARED")&&p.version()!=sourceVersion)throw error(HttpStatus.CONFLICT,"Progress preview changed; review again");if(state.equals("SHARED")&&effective(old,a)&&old.progressVersion()==sourceVersion)return old;var counts=preview(p);String now=clock.instant().truncatedTo(ChronoUnit.MICROS).toString();
   var v=state.equals("WITHDRAWN")?new Share(old.shareId(),old.groupId(),old.spaceId(),old.courseId(),old.participantId(),Math.addExact(old.version(),1),state,old.policyVersion(),old.membershipVersion(),old.enrollmentId(),old.enrollmentVersion(),old.courseVersion(),old.progressVersion(),old.completedStudies(),old.totalStudies(),"OWNER",now):new Share(old==null?ids.next():old.shareId(),ref.groupId(),ref.spaceId(),ref.courseId(),ref.principalId(),old==null?1:Math.addExact(old.version(),1),state,a.policyVersion(),a.membershipVersion(),ref.enrollmentId(),ref.enrollmentVersion(),ref.courseVersion(),sourceVersion,counts.completedStudies(),counts.totalStudies(),"OWNER",now);
   if(old==null)sql.update("INSERT INTO course_progress_share VALUES (?,?,?,?,?,?,?,?,?,?::jsonb)",v.shareId(),p.progressId(),v.groupId(),v.spaceId(),v.courseId(),v.participantId(),v.version(),state,v.policyVersion(),json.writeValueAsString(v));else sql.update("UPDATE course_progress_share SET version=?,state=?,policy_version=?,snapshot=?::jsonb WHERE share_id=?",v.version(),state,v.policyVersion(),json.writeValueAsString(v),v.shareId());record(v,trace);return v;
  });
 }
 History history(CourseContextClient.Sharing a,long before,int limit){var v=own(a.learning());if(v==null)return new History(List.of(),null);var rows=sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM course_progress_share_revision WHERE share_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Share.class)),v.shareId(),before,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new History(items,rows.size()>limit?items.getLast().version():null);}
 Scan scan(CourseContextClient.Sharing a,UUID after,int limit){if(!a.learning().role().equals("OWNER"))throw error(HttpStatus.FORBIDDEN,"Group OWNER required");if(!a.enabled())return new Scan(List.of(),null);var ref=a.learning();var rows=sql.query("SELECT snapshot::text FROM course_progress_share WHERE group_id=? AND space_id=? AND course_id=? AND state='SHARED' AND policy_version=? AND share_id>? ORDER BY share_id LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Share.class),ref.groupId(),ref.spaceId(),ref.courseId(),a.policyVersion(),after==null?new UUID(0,0):after,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Scan(items,rows.size()>limit?items.getLast().shareId():null);}
 static Page filter(Scan scan,CourseContextClient.Sharing a){if(!a.learning().role().equals("OWNER"))throw error(HttpStatus.FORBIDDEN,"Group OWNER required");if(!a.enabled())return new Page(List.of(),null);var eligible=new HashMap<UUID,CourseContextClient.Eligible>();for(var e:a.eligibleParticipants())eligible.put(e.principalId(),e);var r=a.learning();var items=new ArrayList<Summary>();for(var s:scan.items()){var e=eligible.get(s.participantId());if(s.state().equals("SHARED")&&s.groupId().equals(r.groupId())&&s.spaceId().equals(r.spaceId())&&s.courseId().equals(r.courseId())&&s.policyVersion()==a.policyVersion()&&e!=null&&s.membershipVersion()==e.membershipVersion()&&s.enrollmentId().equals(e.enrollmentId())&&s.enrollmentVersion()==e.enrollmentVersion())items.add(new Summary(s.shareId(),s.participantId(),s.completedStudies(),s.totalStudies(),s.updatedAt()));}return new Page(List.copyOf(items),scan.nextAfter());}
 private void record(Share v,String trace){var at=Timestamp.from(Instant.parse(v.updatedAt()));sql.update("INSERT INTO course_progress_share_revision VALUES (?,?,?,?,?,?::jsonb)",ids.next(),v.shareId(),v.version(),v.participantId(),at,json.writeValueAsString(v));var p=CourseProgressShareSnapshotV1.newBuilder().setShareId(v.shareId().toString()).setGroupId(v.groupId().toString()).setSpaceId(v.spaceId().toString()).setCourseId(v.courseId().toString()).setParticipantId(v.participantId().toString()).setVersion(v.version()).setState(v.state()).setPolicyVersion(v.policyVersion()).setMembershipVersion(v.membershipVersion()).setEnrollmentId(v.enrollmentId().toString()).setEnrollmentVersion(v.enrollmentVersion()).setCourseVersion(v.courseVersion()).setProgressVersion(v.progressVersion()).setCompletedStudies(v.completedStudies()).setTotalStudies(v.totalStudies()).setAudience(v.audience()).setUpdatedAt(v.updatedAt()).build();var id=ids.next();String type=v.state().equals("SHARED")?"CourseProgressSummaryShared":"CourseProgressSummaryWithdrawn";var e=CourseProgressShareEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(at.toInstant().toEpochMilli()).setProducer("learning-service").setAggregateType("CourseProgressShare").setAggregateId(v.shareId().toString()).setSpaceId(v.spaceId().toString()).setActorId(v.participantId().toString()).setTraceId(trace).setPayload(p.toByteString()).build();sql.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,'course-progress-share',?,?,?,?,'learning','course-progress-share-events','1',?)",id,v.shareId(),type,at,trace,e.toByteArray());}
}
